-- StarterGui.KGH.MainFrame.RealFrame.FullLightButton.loader2
local function C_11()
local script = G2L["11"];
	local btn = script.Parent
	local Lighting = game:GetService("Lighting")
	
	local isFullbright = false
	local originalSettings = nil -- Variabel buat menyimpan settingan asli game
	
	-- Fungsi untuk menyimpan settingan awal game
	local function saveOriginalSettings()
		originalSettings = {
			Brightness = Lighting.Brightness,
			ClockTime = Lighting.ClockTime,
			GlobalShadows = Lighting.GlobalShadows,
			Ambient = Lighting.Ambient,
			OutdoorAmbient = Lighting.OutdoorAmbient,
			FogEnd = Lighting.FogEnd,
			FogStart = Lighting.FogStart
		}
	end
	
	-- Pengunci Fog agar tetap hilang selama Fullbright ON
	Lighting:GetPropertyChangedSignal("FogEnd"):Connect(function()
		if isFullbright and Lighting.FogEnd ~= 100000 then
			Lighting.FogEnd = 100000
		end
	end)
	
	-- Event Klik Tombol
	btn.MouseButton1Click:Connect(function()
		isFullbright = not isFullbright
	
		if isFullbright then
			-- Simpan settingan asli HANYA pada klik pertama kali
			if not originalSettings then
				saveOriginalSettings()
			end
	
			-- Terapkan Fullbright + Anti-Fog
			Lighting.Brightness = 1.5
			Lighting.ClockTime = 12
			Lighting.GlobalShadows = false
			Lighting.Ambient = Color3.fromRGB(180, 180, 180) -- Soft white (tidak silau)
			Lighting.OutdoorAmbient = Color3.fromRGB(180, 180, 180)
			Lighting.FogEnd = 100000
			Lighting.FogStart = 0
	
			-- Sembunyikan efek Atmosphere / Blur bawaan map jika ada
			for _, effect in ipairs(Lighting:GetChildren()) do
				if effect:IsA("Atmosphere") or effect:IsA("DepthOfField") then
					effect.Parent = workspace -- Dipindahkan sementara (bukan di-destroy agar bisa balik)
				end
			end
	
			btn.Text = "Fullbright: ON"
		else
			-- Kembalikan SEMUA settingan persis seperti awal game
			if originalSettings then
				Lighting.Brightness = originalSettings.Brightness
				Lighting.ClockTime = originalSettings.ClockTime
				Lighting.GlobalShadows = originalSettings.GlobalShadows
				Lighting.Ambient = originalSettings.Ambient
				Lighting.OutdoorAmbient = originalSettings.OutdoorAmbient
				Lighting.FogEnd = originalSettings.FogEnd
				Lighting.FogStart = originalSettings.FogStart
			end
	
			-- Kembalikan efek Atmosphere / DepthOfField yang tadi dipindah
			for _, effect in ipairs(workspace:GetChildren()) do
				if effect:IsA("Atmosphere") or effect:IsA("DepthOfField") then
					effect.Parent = Lighting
				end
			end
	
			btn.Text = "Fullbright: OFF"
		end
	end)
end;
task.spawn(C_11);

return G2L["1"], require;
